create policy manufacturing_delete_routing_operations on public.routing_operations for delete to authenticated using(exists(select 1 from public.bom_versions b where b.id=bom_version_id and b.company_id=public.current_company_id() and b.business_unit_id=public.current_business_unit_id() and b.status='draft' and public.has_module_permission(b.company_id,'production','delete')));
